def next_state(state, ages, cov_trace, now, cfg):
    stale = [k for k, a in ages.items() if a > cfg.timeouts[k]]
    if ages['output'] > cfg.timeouts['output'] or cov_trace > cfg.cov_critical:
        return 'LOST'
    if stale or cov_trace > cfg.cov_warn:
        return 'DEGRADED'
    return 'OK' if state.healthy_for(now) >= cfg.recovery_hold_s else state.name

